import re

def calc(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                # integer division truncating toward zero
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                val = q
        return val

    def parse_factor():
        neg_count = 0
        while peek() == '-':
            advance()
            neg_count += 1
        val = parse_primary()
        if neg_count % 2 == 1:
            val = -val
        return val

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            advance()  # ')'
            return val
        else:
            advance()
            return int(tok)

    result = parse_expr()
    return result

